package dev.almaz.pathway.domain;
import jakarta.persistence.*;import java.time.*;import java.math.*;
@Entity @Table(name="applications") public class Application { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String owner="demo"; private String company; private String role; private String status; private LocalDate appliedOn; private String nextStep; private String notes;
 public Application(){} public Application(String company,String role,String status,LocalDate appliedOn,String nextStep,String notes){this.company=company;this.role=role;this.status=status;this.appliedOn=appliedOn;this.nextStep=nextStep;this.notes=notes;} public Long getId(){return id;} public String getOwner(){return owner;} public void setOwner(String x){owner=x;} public String getCompany(){return company;} public void setCompany(String v){company=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getAppliedOn(){return appliedOn;} public void setAppliedOn(LocalDate v){appliedOn=v;} public String getNextStep(){return nextStep;} public void setNextStep(String v){nextStep=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;}
}
